import { defineCourse } from './Course';
import type { HoleDefinition } from './Hole';
import type { Course } from './types';

export interface CourseBuilderOptions {
  id: string;
  name: string;
  themeId: string;
  version?: number;
}

/**
 * Small fluent API used by course-data modules. It intentionally only builds
 * descriptors; obstacle behavior belongs to runtime obstacle implementations.
 */
export class CourseBuilder {
  private readonly holes: HoleDefinition[] = [];
  private readonly options: Required<CourseBuilderOptions>;

  constructor(options: CourseBuilderOptions) {
    this.options = { ...options, version: options.version ?? 1 };
  }

  addHole(hole: HoleDefinition): this {
    this.holes.push(hole);
    return this;
  }

  addHoles(holes: readonly HoleDefinition[]): this {
    this.holes.push(...holes);
    return this;
  }

  build(): Course {
    return defineCourse({
      id: this.options.id,
      name: this.options.name,
      themeId: this.options.themeId,
      version: this.options.version,
      holes: [...this.holes],
    });
  }
}

export function createCourseBuilder(options: CourseBuilderOptions): CourseBuilder {
  return new CourseBuilder(options);
}
