import type { Hole as HoleDescriptor } from './types';

/** Input accepted by the level builder for a single hole. */
export type HoleDefinition = HoleDescriptor;

/**
 * Creates a hole descriptor while preserving literal obstacle/surface types.
 * Runtime systems consume plain data, so course modules stay serializable.
 */
export function defineHole<const T extends HoleDefinition>(hole: T): T {
  return hole;
}

export function validateHole(hole: HoleDefinition): void {
  if (!hole.id.trim()) throw new Error('Hole id must not be empty');
  if (!hole.name.trim()) throw new Error(`Hole ${hole.id}: name must not be empty`);
  if (!Number.isInteger(hole.par) || hole.par < 1) {
    throw new Error(`Hole ${hole.id}: par must be a positive integer`);
  }
  if (!(hole.cup.radius > 0) || !(hole.cup.captureDepth > 0)) {
    throw new Error(`Hole ${hole.id}: cup dimensions must be positive`);
  }

  const axes = ['x', 'y', 'z'] as const;
  for (const axis of axes) {
    if (hole.bounds.min[axis] > hole.bounds.max[axis]) {
      throw new Error(`Hole ${hole.id}: invalid ${axis}-axis bounds`);
    }
  }

  const ids = new Set<string>();
  for (const item of [...hole.surfaces, ...hole.obstacles]) {
    if (!item.id.trim()) throw new Error(`Hole ${hole.id}: element id must not be empty`);
    if (ids.has(item.id)) throw new Error(`Hole ${hole.id}: duplicate element id "${item.id}"`);
    ids.add(item.id);
  }
}
