import type { Course as CourseDescriptor } from './types';
import { validateHole } from './Hole';

/** Input accepted by the level builder for a complete course. */
export type CourseDefinition = CourseDescriptor;

/** Keeps course data as plain serializable objects and retains literal types. */
export function defineCourse<const T extends CourseDefinition>(course: T): T {
  validateCourse(course);
  return course;
}

export function validateCourse(course: CourseDefinition): void {
  if (!course.id.trim()) throw new Error('Course id must not be empty');
  if (!course.name.trim()) throw new Error(`Course ${course.id}: name must not be empty`);
  if (!course.themeId.trim()) throw new Error(`Course ${course.id}: themeId must not be empty`);
  if (!Number.isInteger(course.version) || course.version < 1) {
    throw new Error(`Course ${course.id}: version must be a positive integer`);
  }
  if (course.holes.length === 0) throw new Error(`Course ${course.id}: at least one hole is required`);

  const ids = new Set<string>();
  for (const hole of course.holes) {
    validateHole(hole);
    if (ids.has(hole.id)) throw new Error(`Course ${course.id}: duplicate hole id "${hole.id}"`);
    ids.add(hole.id);
  }
}
